// Paths emitted by code generators — TanStack Router's `routeTree.gen.ts`,
// GraphQL/codegen output, and the like. Generated files follow their generator's
// own style and are rewritten on every regen, so holding them to the house lint
// and format rules is pure noise (and churns the diff). Both `lint` and `fmt`
// ignore these by default, sourced from this one array so the two stay in
// lockstep. The `.gen.{js,ts}` convention is the common marker; consumers extend
// per-project via `lint({ ignores })` / `fmt({ ignores })`, which append.
const GENERATED_PATHS = ['**/*.gen.{js,ts}', '**/*.generated.{js,ts}'] as const;

// Paths emitted by agents — Claude, Codex, Superpowers, etc. These are not
// generated by the project itself, but by external agents. They are also rewritten
// on every regen, so holding them to the house lint and format rules is pure noise
// (and churns the diff). Both `lint` and `fmt` ignore these by default, sourced from
// this one array so the two stay in lockstep. Consumers extend per-project via
// `lint({ ignores })` / `fmt({ ignores })`, which append.
const AGENT_IGNORES = ['.claude/**', '.codex/**', '.superpowers/**', 'docs/superpowers/**'];

// Paths emitted by package managers — pnpm, bun, etc. These are not generated by
// the project itself, but by external package managers.
const PACKAGE_MANAGER_IGNORES = ['node_modules', 'pnpm-lock.yaml', 'bun.lock'] as const;

// Paths emitted by build artifacts — dist, build, .turbo, .vite. These are not
// generated by the project itself, but by external build tools.
const BUILD_ARTIFACT_IGNORES = ['dist/**', 'build/**', '.turbo/**', '.vite/**'] as const;

// Paths emitted by test artifacts — coverage. These are not generated by the project
// itself, but by external test tools.
const TEST_ARTIFACT_IGNORES = ['coverage/**'] as const;

// The global ignore list — keeps oxfmt and eslint off generated/output files.
const GLOBAL_IGNORES = [
  ...BUILD_ARTIFACT_IGNORES,
  ...TEST_ARTIFACT_IGNORES,
  ...PACKAGE_MANAGER_IGNORES,
  ...GENERATED_PATHS,
  ...AGENT_IGNORES,
] as const;

export {
  AGENT_IGNORES,
  BUILD_ARTIFACT_IGNORES,
  GENERATED_PATHS,
  GLOBAL_IGNORES,
  PACKAGE_MANAGER_IGNORES,
  TEST_ARTIFACT_IGNORES,
};
